<?php
 namespace Pterodactyl\Models; use Pterodactyl\Rules\Username; use Pterodactyl\Facades\Activity; use Illuminate\Support\Str; use Illuminate\Support\Collection; use Illuminate\Validation\Rules\In; use Illuminate\Auth\Authenticatable; use Illuminate\Notifications\Notifiable; use Illuminate\Database\Eloquent\Builder; use Pterodactyl\Contracts\Models\Identifiable; use Pterodactyl\Models\Traits\HasAccessTokens; use Illuminate\Auth\Passwords\CanResetPassword; use Pterodactyl\Traits\Helpers\AvailableLanguages; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Database\Eloquent\Relations\HasOne; use Illuminate\Foundation\Auth\Access\Authorizable; use Pterodactyl\Models\Traits\HasRealtimeIdentifier; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Relations\MorphToMany; use Illuminate\Contracts\Auth\Authenticatable as AuthenticatableContract; use Illuminate\Contracts\Auth\Access\Authorizable as AuthorizableContract; use Illuminate\Contracts\Auth\CanResetPassword as CanResetPasswordContract; use Pterodactyl\Notifications\SendPasswordReset as ResetPasswordNotification; #[Attributes\Identifiable('user')] class User extends Model implements AuthenticatableContract, AuthorizableContract, CanResetPasswordContract, Identifiable { use Authenticatable; use Authorizable; use AvailableLanguages; use CanResetPassword; use HasAccessTokens; use Notifiable; use HasFactory; use HasRealtimeIdentifier; public const USER_LEVEL_USER = 0; public const USER_LEVEL_ADMIN = 1; public const RESOURCE_NAME = 'user'; protected string $accessLevel = 'all'; protected $table = 'users'; protected $fillable = [ 'external_id', 'username', 'email', 'name_first', 'name_last', 'password', 'language', 'use_totp', 'totp_secret', 'totp_authenticated_at', 'gravatar', 'root_admin', 'demo', 'staff', ]; protected $casts = [ 'root_admin' => 'boolean', 'demo' => 'boolean', 'staff' => 'boolean', 'use_totp' => 'boolean', 'gravatar' => 'boolean', 'totp_authenticated_at' => 'datetime', 'dezerx_preferences' => 'array', ]; protected $hidden = ['password', 'remember_token', 'totp_secret', 'totp_authenticated_at']; protected $attributes = [ 'external_id' => null, 'root_admin' => false, 'demo' => false, 'staff' => false, 'language' => 'en', 'use_totp' => false, 'totp_secret' => null, ]; public static array $validationRules = [ 'uuid' => 'required|string|size:36|unique:users,uuid', 'email' => 'required|email:strict|between:1,191|unique:users,email', 'external_id' => 'sometimes|nullable|string|max:191|unique:users,external_id', 'username' => 'required|between:1,191|unique:users,username', 'name_first' => 'required|string|between:1,191', 'name_last' => 'required|string|between:1,191', 'password' => 'sometimes|nullable|string', 'root_admin' => 'boolean', 'demo' => 'boolean', 'staff' => 'boolean', 'language' => 'string', 'use_totp' => 'boolean', 'totp_secret' => 'nullable|string', ]; public static function getRules(): array { $rules = parent::getRules(); $rules['language'][] = new In(array_keys((new self())->getAvailableLanguages())); $rules['username'][] = new Username(); return $rules; } public function toVueObject(): array { return Collection::make($this->toArray())->except(['id', 'external_id']) ->merge([ 'identifier' => $this->identifier, 'avatar_hash' => md5(Str::lower($this->email)), 'avatar_url' => \Pterodactyl\Services\Dezerx\Avatars::custom($this), ]) ->toArray(); } public function sendPasswordResetNotification($token) { Activity::event('auth:reset-password') ->withRequestMetadata() ->subject($this) ->log('sending password reset email'); $this->notify(new ResetPasswordNotification($token)); } public function setUsernameAttribute(string $value) { $this->attributes['username'] = mb_strtolower($value); } public function getNameAttribute(): string { return trim($this->name_first . ' ' . $this->name_last); } public function servers(): HasMany { return $this->hasMany(Server::class, 'owner_id'); } public function staffProfile(): HasOne { return $this->hasOne(\Pterodactyl\Models\Dezerx\StaffProfile::class, 'user_id'); } public function staffSessions(): HasMany { return $this->hasMany(\Pterodactyl\Models\Dezerx\StaffRequest::class, 'staff_id'); } public function isStaff(): bool { return $this->staff === true; } public function apiKeys(): HasMany { return $this->hasMany(ApiKey::class) ->where('key_type', ApiKey::TYPE_ACCOUNT); } public function recoveryTokens(): HasMany { return $this->hasMany(RecoveryToken::class); } public function sshKeys(): HasMany { return $this->hasMany(UserSSHKey::class); } public function activity(): MorphToMany { return $this->morphToMany(ActivityLog::class, 'subject', 'activity_log_subjects'); } public function accessibleServers(): Builder { return Server::query() ->select('servers.*') ->leftJoin('subusers', 'subusers.server_id', '=', 'servers.id') ->where(function (Builder $builder) { $builder->where('servers.owner_id', $this->id)->orWhere(function (Builder $inner) { $inner->where('subusers.user_id', $this->id)->where(function (Builder $access) { $access->whereNull('subusers.dezerx_staff_request_id')->orWhereExists(function ($query) { $query->selectRaw('1')->from('dezerx_staff_requests')->whereColumn('dezerx_staff_requests.id', 'subusers.dezerx_staff_request_id')->where('dezerx_staff_requests.status', 'active')->where(function ($window) { $window->whereNull('dezerx_staff_requests.expires_at')->orWhere('dezerx_staff_requests.expires_at', '>', now()); }); }); }); }); }) ->groupBy('servers.id'); } } 